 24	
 25	/** Build a minimal valid insight input (no id). */
 26	function makeInsightInput(overrides: Partial<Omit<Insight, 'id'>> = {}): Omit<Insight, 'id'> {
 27	  return {
 28	    scope: 'global',
 29	    title: 'Default title',
 30	    content: 'Default content',
 31	    category: 'general',
 32	    tags: [],
 33	    source: 'test',
 34	    created_at: '2026-01-01T00:00:00Z',
 35	    confidence: 0.8,
 36	    ...overrides,
 37	  };
 38	}
