 40	// ---------------------------------------------------------------------------
 41	// Suite
 42	// ---------------------------------------------------------------------------
 43	
 44	describe('WP-001 Knowledge Handler Foundations', () => {
 45	  let ledgerRoot: string;
 46	  let manager: KnowledgeStoreManager;
 47	
 48	  beforeEach(async () => {
 49	    ledgerRoot = await mkdtemp(join(tmpdir(), 'api-knowledge-test-'));
 50	    manager = new KnowledgeStoreManager(ledgerRoot);
 51	  });
 52	
 53	  afterEach(async () => {
 54	    await rm(ledgerRoot, { recursive: true, force: true });
 55	  });
 56	
 57	  // ─── handleListKnowledge ────────────────────────────────────────────────
 58	
 59	  describe('handleListKnowledge', () => {
 60	    // AC-7: empty store returns empty array
 61	    it('AC-7: returns empty array when no insights exist', async () => {
 62	      const result = await handleListKnowledge(ledgerRoot);
 63	      expect(result).toEqual([]);
 64	    });
 65	
 66	    // AC-1: no params returns all insights from both global and project stores
 67	    it('AC-1: returns all insights from global and project stores when no params given', async () => {
 68	      await manager.addInsight(makeInsightInput({ scope: 'global', title: 'Global insight' }));
 69	      await manager.addInsight(
 70	        makeInsightInput({ scope: 'project', project_slug: 'my-project', title: 'Project insight' })
 71	      );
 72	
 73	      const result = await handleListKnowledge(ledgerRoot);
 74	      expect(result).toHaveLength(2);
 75	      const titles = result.map((i) => i.title);
 76	      expect(titles).toContain('Global insight');
 77	      expect(titles).toContain('Project insight');
 78	    });
 79	
 80	    // AC-2: scope: 'global' returns only global insights
 81	    it('AC-2: scope: global returns only global insights', async () => {
 82	      await manager.addInsight(makeInsightInput({ scope: 'global', title: 'Global A' }));
 83	      await manager.addInsight(
 84	        makeInsightInput({ scope: 'project', project_slug: 'proj', title: 'Project B' })
 85	      );
 86	
 87	      const result = await handleListKnowledge(ledgerRoot, { scope: 'global' });
 88	      expect(result).toHaveLength(1);
 89	      expect(result[0]!.scope).toBe('global');
 90	      expect(result[0]!.title).toBe('Global A');
 91	    });
 92	
 93	    // AC-3: scope: 'project' + project_slug returns only that project's insights
 94	    it('AC-3: scope: project with project_slug returns only that project\'s insights', async () => {
 95	      await manager.addInsight(makeInsightInput({ scope: 'global', title: 'Global' }));
 96	      await manager.addInsight(
 97	        makeInsightInput({ scope: 'project', project_slug: 'alpha', title: 'Alpha insight' })
 98	      );
 99	      await manager.addInsight(
100	        makeInsightInput({ scope: 'project', project_slug: 'beta', title: 'Beta insight' })

 1	/**
 2	 * GUI API Route Handlers
 3	 *
 4	 * Pure async functions — one per REST endpoint. Each handler accepts parsed
 5	 * request parameters and returns a result object (or throws a structured error).
 6	 * The HTTP server (gui/server.ts) calls these handlers and maps results to HTTP
 7	 * responses.
 8	 *
 9	 * Error shape:  { code: string, message: string, details?: unknown }
10	 *   NOT_FOUND        → 404
11	 *   FORBIDDEN        → 403
12	 *   VALIDATION_ERROR → 400
13	 *   (unhandled)      → 500
14	 *
15	 * STDIO discipline: this file never writes to process.stdout.
16	 */
17	
