24	import { assertSafeSegment } from '../src/utils/path-validator.js';
25	import { readProjectName } from '../src/utils/read-project-name.js';
26	import { PLAN_ARCHIVE_FILENAME, SYNTHESIS_ARCHIVE_FILENAME, DIALOGUES_DIR, CHUNKS_DIR } from '../src/utils/constants.js';
27	import {
28	  PIPELINE_AGENT_MAP,
29	  DEFAULT_PIPELINE_STAGES,
