73	
74	// ---------------------------------------------------------------------------
75	// Internal helpers
76	// ---------------------------------------------------------------------------
77	
78	function notFound(message: string): never {
79	  throw new ApiError('NOT_FOUND', message);
80	}
81	
82	function forbidden(message: string): never {
83	  throw new ApiError('FORBIDDEN', message);
84	}
85	
86	function conflict(message: string): never {
87	  throw new ApiError('CONFLICT', message);
88	}
89	
90	function validationError(message: string, details?: unknown): never {
91	  throw new ApiError('VALIDATION_ERROR', message, details);
92	}
93	
94	/**
95	 * Allowlist for WP IDs and queue entry IDs: must start with alnum, then word chars or hyphens.
96	 * Note: `\w` includes underscore intentionally — WP IDs (`WP-001`) and queue entry IDs may
97	 * contain underscores in future formats. This is permissive by design.
98	 */
99	const SAFE_ID_PATTERN = /^[A-Za-z0-9][\w-]*$/;

101	/**
102	 * Guards against path-traversal attacks on the project slug URL parameter.
103	 *
104	 * Rejects any slug that does not satisfy the safe-slug rules
105	 * (lowercase alphanumeric + hyphens, must start with an alphanumeric character).
106	 * This reuses the same slug format enforced on project creation and rename,
107	 * ensuring only lowercase alphanumeric characters and hyphens are accepted —
108	 * eliminating path separators and traversal sequences by design.
109	 *
110	 * @param slug - The raw slug string extracted from the request URL.
111	 */
112	function assertSafeSlug(slug: string): void {
113	  if (!assertSafeSegment(slug)) {
114	    notFound(`Invalid project slug: '${slug}'.`);
115	  }
116	}
117	
118	/**
119	 * Guards against path-traversal attacks on the work-package ID URL parameter.
120	 *
121	 * Rejects any wpId that does not match {@link SAFE_ID_PATTERN}
122	 * (`/^[A-Za-z0-9][\w-]*$/`). Requires an alphanumeric first character,
123	 * blocking `..`, `.`, and all path separators by design.
124	 *
125	 * @param wpId - The raw work-package ID string extracted from the request URL.
126	 */
127	function assertSafeWpId(wpId: string): void {
128	  if (!wpId || !SAFE_ID_PATTERN.test(wpId)) {
129	    notFound(`Invalid work-package ID: '${wpId}'.`);
130	  }
131	}
132	
133	/**
134	 * Guards against path-traversal attacks on the orchestrator queue entry ID
135	 * URL parameter.
136	 *
137	 * Rejects any id that does not match {@link SAFE_ID_PATTERN}
138	 * (`/^[A-Za-z0-9][\w-]*$/`). Requires an alphanumeric first character,
139	 * blocking `..`, `.`, and all path separators by design.
140	 *
141	 * @param id - The raw queue entry ID string extracted from the request URL.
142	 */
143	function assertSafeQueueId(id: string): void {
144	  if (!id || !SAFE_ID_PATTERN.test(id)) {
145	    notFound(`Invalid queue entry ID: '${id}'.`);
146	  }
147	}
148	
149	/**
150	 * Resolves a LedgerStore for URL-parameter-driven handlers.
151	 *
152	 * Locates the namespaced storage directory via resolveProjectDir(), reads
153	 * .meta.json for plan_path, and constructs a LedgerStore from it. Callers
154	 * must validate `slug` (via assertSafeSlug) before calling. If `repoName` is
155	 * provided, it is validated here via assertSafeSlug before being joined with
156	 * `slug` to form a qualified `{repo}/{slug}` lookup.
157	 *
158	 * @remarks **Security contract — AMBIGUOUS → NOT_FOUND downgrade:**
159	 * When `resolveProjectDir()` throws an AMBIGUOUS error (multiple repos contain
160	 * this slug), this function intentionally downgrades it to the same NOT_FOUND
161	 * ApiError used for a missing project. This prevents callers from learning
162	 * that a slug exists in any repository (cross-namespace existence leak).
163	 * The inline comment in the catch block documents the downgrade decision;
164	 * do not restore the original AMBIGUOUS message without a security review.
165	 *
166	 * @throws ApiError NOT_FOUND when the project cannot be located, is ambiguous
167	 *   across namespaces, or has no metadata.
168	 */
169	async function resolveProjectStore(
170	  ledgerRoot: string,
171	  slug: string,
172	  repoName?: string
173	): Promise<LedgerStore> {
174	  if (repoName !== undefined) {
175	    assertSafeSlug(repoName);
176	  }
177	  const slugOrQualified = repoName !== undefined ? `${repoName}/${slug}` : slug;
178	
179	  let storageDir: string;
180	  try {
181	    storageDir = await resolveProjectDir(slugOrQualified, ledgerRoot);
182	  } catch (err) {
183	    const msg = err instanceof Error ? err.message : String(err);
184	    // Intentionally downgrade AMBIGUOUS to NOT_FOUND: the caller must not learn
185	    // that multiple repos contain this slug (prevents cross-namespace existence leak).
186	    if (msg.startsWith('NOT_FOUND') || msg.startsWith('AMBIGUOUS')) {
187	      notFound(`Project '${slug}' not found.`);
188	    }
189	    throw err;
190	  }
191	
192	  try {
193	    const raw = await readFile(join(storageDir, '.meta.json'), 'utf-8');
194	    const meta = ProjectMetaSchema.parse(JSON.parse(raw));
195	    return new LedgerStore(meta.plan_path, ledgerRoot);
196	  } catch {
197	    notFound(`Project '${slug}' not found or has no metadata.`);
198	  }
199	}
