1671	 * Lists (or searches) knowledge insights stored in the ledger's `.knowledge/` directory.
1672	 *
1673	 * - When `query` is present, delegates to `KnowledgeStoreManager.searchInsights()`.
1674	 * - Otherwise calls `KnowledgeStoreManager.listInsights()` with scope/category/tags filters.
1675	 * - `scope` is validated via `InsightScope.safeParse()`; unrecognised values are silently
1676	 *   treated as "no scope filter" rather than causing an error.
1677	 * - `tags` is a comma-separated string that is split before being forwarded.
1678	 * - `limit` and `offset` are coerced to non-negative integers; invalid/missing values
1679	 *   are silently ignored (limit → undefined, offset → 0).
1680	 */
1681	export async function handleListKnowledge(
1682	  ledgerRoot: string,
1683	  params: KnowledgeListParams = {}
1684	): Promise<Insight[]> {
1685	  const manager = new KnowledgeStoreManager(ledgerRoot);
1686	
1687	  // Validate scope — unrecognised values fall back to undefined (no filter).
1688	  const scopeResult = InsightScope.safeParse(params.scope);
1689	  const scope = scopeResult.success ? scopeResult.data : undefined;
1690	
1691	  const category = params.category ?? undefined;
1692	  const project_slug = params.project_slug ?? undefined;
1693	
1694	  // Split comma-separated tags; ignore empty segments.
1695	  const tags =
1696	    params.tags && params.tags.trim().length > 0
1697	      ? params.tags
1698	          .split(',')
1699	          .map((t) => t.trim())
1700	          .filter((t) => t.length > 0)
1701	      : undefined;
1702	
1703	  // Coerce pagination params.
1704	  const limitRaw = params.limit !== undefined ? Math.floor(Number(params.limit)) : NaN;
1705	  const limit = !isNaN(limitRaw) && limitRaw > 0 ? limitRaw : undefined;
1706	
1707	  const offsetRaw = params.offset !== undefined ? Math.floor(Number(params.offset)) : NaN;
1708	  const offset = !isNaN(offsetRaw) && offsetRaw >= 0 ? offsetRaw : 0;
1709	
1710	  if (params.query && params.query.trim().length > 0) {
1711	    return manager.searchInsights(params.query.trim(), { scope, project_slug, category });
1712	  }
1713	
1714	  return manager.listInsights({ scope, category, tags, project_slug, limit, offset });
